import yaml, pathlib
from collections import defaultdict

titles = defaultdict(list)
title_ne_filename = []
aliases = defaultdict(list)

skip_dirs = {'.obsidian', '.trash', '.git', 'raw', 'wiki', 'output'}

for p in pathlib.Path('.').rglob('*.md'):
    if any(part in skip_dirs for part in p.parts):
        continue
    try:
        text = p.read_text(encoding='utf-8', errors='ignore')
    except Exception:
        continue
    if not text.startswith('---'):
        continue
    parts = text.split('---', 2)
    if len(parts) < 3:
        continue
    try:
        fm = yaml.safe_load(parts[1])
    except Exception:
        continue
    if not isinstance(fm, dict):
        continue
    t = fm.get('title')
    if isinstance(t, str) and t.strip():
        titles[t.strip()].append(str(p))
        if t.strip() != p.stem:
            title_ne_filename.append((str(p), t.strip()))
    al = fm.get('aliases')
    if isinstance(al, list):
        for a in al:
            if isinstance(a, str) and a.strip():
                aliases[a.strip()].append(str(p))

print('=== DUPLICATE title: FIELDS (same title, different files) ===')
for t, files in titles.items():
    if len(files) > 1:
        print(f'{t!r}:')
        for f in files:
            print(f'  - {f}')

print()
print('=== ALIAS collides with another note ALIAS (same alias, 2+ files) ===')
for a, files in aliases.items():
    if len(files) > 1:
        print(f'{a!r}:')
        for f in files:
            print(f'  - {f}')

print()
print('=== ALIAS collides with a real note TITLE elsewhere ===')
for a, files in aliases.items():
    if a in titles:
        title_owners = titles[a]
        alias_owners = files
        if set(title_owners) - set(alias_owners):
            print(f'{a!r}: alias in {alias_owners} vs title in {title_owners}')
