import yaml, pathlib, glob
from collections import defaultdict

alias_owner = defaultdict(list)
for f in glob.glob('**/*.md', recursive=True):
    if f.startswith('99_Archive/') or f.startswith('.'):
        continue
    p = pathlib.Path(f)
    try:
        text = p.read_text(encoding='utf-8', errors='ignore')
        if not text.startswith('---'):
            continue
        fm = yaml.safe_load(text.split('---',2)[1])
    except Exception:
        continue
    if not fm:
        continue
    aliases = fm.get('aliases')
    if not aliases or not isinstance(aliases, list):
        continue
    for a in aliases:
        if isinstance(a, str) and a.strip():
            alias_owner[a.strip()].append(f)

collisions = {a: files for a, files in alias_owner.items() if len(files) > 1}
print(f'Remaining alias-alias collisions: {len(collisions)}')
for a, files in collisions.items():
    print(f'  {a!r}: {files}')
